#pragma once
void testPackSources(){
    using namespace bridge;using namespace bridge::shaderloader;
    const auto fails=[](auto fn){try{fn();}catch(const std::exception&){return true;}return false;};
    const auto read=[](std::string name){std::ifstream input("outputs/native-renderer-verification/"+name,std::ios::binary);requireCPU(bool(input),"Missing pack source fixture.");return std::vector<uint8_t>(std::istreambuf_iterator<char>(input),{});};
    const auto bytes=read("pack-source-fixture.bin");const auto sources=PackSources::decode(bytes);requireCPU(sources->names().size()==8&&sources->contains("block.properties"),"ZIP/directory snapshot lost source files.");
    const auto vertex=IncludeResolver::expand(*sources,"gbuffers_terrain.vsh"),fragment=IncludeResolver::expand(*sources,"gbuffers_terrain.fsh"),negative=IncludeResolver::expand(*sources,"faulty.fsh");
    requireCPU(vertex.text.starts_with("#version 330 core\n#line 2 0\n")&&vertex.text.find("#include")==std::string::npos&&vertex.dependencies.size()==2&&vertex.sourcePaths==std::vector<std::string>{"gbuffers_terrain.vsh","lib/math.glsl","lib/constants.glsl"},"Version ordering, root-relative/parent-relative include or file IDs changed.");
    requireCPU(vertex.text.find("#line 1 2\nconst float packConstant")!=std::string::npos&&vertex.text.find("#line 2 1\nvec4 packPosition")!=std::string::npos&&vertex.text.find("#line 4 0\nvoid main")!=std::string::npos,"Include source line restoration is wrong.");
    requireCPU(fragment.sourcePaths==std::vector<std::string>{"gbuffers_terrain.fsh","lib/tint.glsl"}&&negative.sourcePaths[1]=="lib/bad.glsl","Fragment diagnostic source map is wrong.");
    const auto write=[](const char* name,const std::string& text){std::ofstream output(std::string("outputs/native-renderer-verification/")+name,std::ios::binary);requireCPU(bool(output),"Cannot write expanded compiler fixture.");output.write(text.data(),static_cast<std::streamsize>(text.size()));requireCPU(bool(output),"Incomplete expanded compiler fixture.");};
    write("pack-include-positive.vert",vertex.text);write("pack-include-positive.frag",fragment.text);write("pack-include-negative.frag",negative.text);write("pack-include-negative.sources.txt","0\tfaulty.fsh\n1\tlib/bad.glsl\n");
    const auto material=preparePackMaterials(*sources,{{"UNAVAILABLE_OPTION",std::nullopt}});
    requireCPU(material.blockIds->resolve(MinecraftBlockState{"minecraft:stone",{},true})==PackBlockId{16777217,true},"Snapshot material text did not reach the existing preprocessor/resolver.");
    for(const auto name:{"../a","/a","a/../b","a/./b","a//b","a\\b","C:/a","CON.glsl","lib/LPT1.inc","lib/end.",""})requireCPU(fails([&]{PackSources::create({{name,"x"}});}),"Unsafe virtual source path was accepted.");
    for(const auto names:{std::pair{"a","a"},std::pair{"a","A"},std::pair{"lib/a","Lib/b"},std::pair{"lib","lib/a"}})requireCPU(fails([&]{PackSources::create({{names.first,"x"},{names.second,"y"}});}),"Duplicate/case-alias/file-parent virtual sources were accepted.");
    for(const auto value:{std::string("\xc0\xaf"),std::string("\xed\xa0\x80"),std::string("\xf4\x90\x80\x80"),std::string("\xe2\x82"),std::string("x\0",2),std::string("\x7f"),std::string("\xef\xbb\xbf")})requireCPU(fails([&]{PackSources::create({{"a.glsl",value}});}),"Invalid UTF-8/control/BOM source was accepted.");
    for(const size_t cut:{size_t(0),size_t(3),size_t(7),size_t(8),bytes.size()-1})requireCPU(fails([&]{PackSources::decode(std::span(bytes).first(cut));}),"Truncated pack snapshot was accepted.");
    for(const auto offset:{0u,4u,8u,12u}){auto bad=bytes;std::fill_n(bad.begin()+offset,4,0xff);requireCPU(fails([&]{PackSources::decode(bad);}),"Malformed pack snapshot size/count/magic was accepted.");}
    auto trailing=bytes;trailing.push_back(0);auto installed=sources;requireCPU(fails([&]{installed=PackSources::decode(trailing);})&&installed==sources,"Failed snapshot read replaced installed source ownership.");
    const auto expand=[](std::vector<std::pair<std::string,std::string>> files){const auto data=PackSources::create(std::move(files));return IncludeResolver::expand(*data,"root.vsh");};
    const auto relative=expand({{"root.vsh","#version 330 core\n#include \"lib/dir/a.glsl\"\n"},{"lib/dir/a.glsl","#include \"../../lib/b.glsl\"\n"},{"lib/b.glsl","// valid\n"}});requireCPU(relative.dependencies.back().to=="lib/b.glsl","In-root parent include was rejected or resolved against host paths.");
    for(const auto root:{"#include \"../escape.glsl\"","#include \"/../escape.glsl\"","#include \"C:/host.glsl\"","#include \"a\\b.glsl\"","#include <a.glsl>","#include MACRO","#include \"a.glsl\" // trailing","#line 1 5","float x;\n#version 330 core","#version 330 core\n#version 330 core","/*\n#include \"a.glsl\"\n*/","/* unfinished","#if 0\n#include \"missing.glsl\"\n#endif"})requireCPU(fails([&]{expand({{"root.vsh",root},{"a.glsl",""}});}),"Unsupported/escaped/missing include or misplaced version was silently accepted.");
    requireCPU(fails([&]{expand({{"root.vsh","#ifndef GUARD\n#define GUARD\n#include \"root.vsh\"\n#endif"}});}),"An include guard hid a pre-conditional cycle.");
    requireCPU(fails([&]{expand({{"root.vsh","#include \"a.glsl\""},{"a.glsl","#include \"root.vsh\""}});}),"Indirect include cycle was accepted.");
    requireCPU(fails([&]{expand({{"root.vsh","#include \"a.glsl\""},{"a.glsl","#version 330 core"}});}),"Included version directive was accepted.");
    const auto repeated=expand({{"root.vsh","#include \"a.glsl\"\n#include \"a.glsl\""},{"a.glsl","#ifndef A\n#define A\nfloat a;\n#endif"}});const auto first=repeated.text.find("float a;");requireCPU(first!=std::string::npos&&repeated.text.find("float a;",first+1)!=std::string::npos&&repeated.sourcePaths.size()==2,"Repeated includes were elided before guard evaluation or allocated new file IDs.");
    auto old=vertex;requireCPU(fails([&]{old=IncludeResolver::expand(*sources,"missing.vsh");})&&old.text==vertex.text,"Failed include expansion replaced a previous complete source.");
    std::vector<std::pair<std::string,std::string>> chain;for(unsigned i=0;i<34;++i)chain.emplace_back(i?"p"+std::to_string(i)+".glsl":"root.vsh",i==33?"":"#include \"/p"+std::to_string(i+1)+".glsl\"\n");requireCPU(fails([&]{expand(chain);}),"Include depth limit was exceeded.");
    std::string many;for(unsigned i=0;i<8192;++i)many+="#include \"a.glsl\"\n";requireCPU(fails([&]{expand({{"root.vsh",many},{"a.glsl",""}});}),"Include visit limit was exceeded.");
    std::string output;for(unsigned i=0;i<9;++i)output+="#include \"a.glsl\"\n";requireCPU(fails([&]{expand({{"root.vsh",output},{"a.glsl",std::string(1024*1024,' ')}});}),"Expanded include output limit was exceeded.");
    requireCPU(fails([&]{PackSources::create({{"a.glsl",std::string(1024*1024+1,' ')}});}),"Individual source size limit was exceeded.");
    std::vector<std::pair<std::string,std::string>> count;for(unsigned i=0;i<4097;++i)count.emplace_back(std::to_string(i),"");requireCPU(fails([&]{PackSources::create(count);}),"Source file count limit was exceeded.");
}
